# Blender scene builder generated by CamTrack (3D camera tracker).
#
# Usage (any of):
#   * Blender > Scripting workspace > Open this file > Run Script
#   * blender --python build_scene.py
#   * blender -b --python build_scene.py -- --save solved_scene.blend
#
# The script is self-contained: all tracking data is embedded below (it also
# looks for scene.json next to this file and prefers it if present). The
# original footage is expected in ./footage/ relative to this script; it is
# attached as the camera background when found.
#
# Tested with Blender 4.x and 5.0.
import json
import math
import os
import sys

import bpy
from mathutils import Matrix, Quaternion, Vector

SCENE_DATA = r"""__SCENE_JSON__"""

CREATE_POINT_EMPTIES = True      # one Empty per reconstructed point
POINT_EMPTY_SIZE = None          # None = automatic from scene size
ONLY_RELIABLE_POINTS = False     # True = skip points flagged unreliable
COLLECTION_NAME = "CamTrack"


def _script_dir():
    try:
        d = os.path.dirname(os.path.abspath(__file__))
        if os.path.isdir(d):
            return d
    except NameError:
        pass
    if bpy.data.filepath:
        return os.path.dirname(bpy.data.filepath)
    return os.getcwd()


def load_data():
    d = _script_dir()
    p = os.path.join(d, "scene.json")
    if os.path.exists(p):
        with open(p, encoding="utf-8") as fh:
            return json.load(fh), d
    return json.loads(SCENE_DATA), d


def get_collection(name, parent):
    col = bpy.data.collections.get(name)
    if col is None:
        col = bpy.data.collections.new(name)
    if col.name not in [c.name for c in parent.children]:
        parent.children.link(col)
    return col


def clear_collection(col):
    for ob in list(col.objects):
        bpy.data.objects.remove(ob, do_unlink=True)
    for ch in list(col.children):
        clear_collection(ch)
        bpy.data.collections.remove(ch)


def iter_fcurves(id_data):
    ad = getattr(id_data, "animation_data", None)
    if not ad or not ad.action:
        return []
    act = ad.action
    if hasattr(act, "fcurves"):           # Blender <= 4.x
        try:
            return list(act.fcurves)
        except Exception:
            pass
    out = []                                # Blender 4.4+/5.x layered actions
    for layer in getattr(act, "layers", []):
        for strip in layer.strips:
            for bag in getattr(strip, "channelbags", []):
                out.extend(bag.fcurves)
    return out


def set_linear(id_data):
    for fc in iter_fcurves(id_data):
        for kp in fc.keyframe_points:
            kp.interpolation = "LINEAR"


def matrix3(m):
    return Matrix([m[0], m[1], m[2]])


def build():
    data, base_dir = load_data()
    scene = bpy.context.scene
    fr = data["frame_range"]
    ft = data["footage"]
    intr = data["intrinsics"]

    # ---- scene settings ----
    scene.render.resolution_x = int(ft["width"])
    scene.render.resolution_y = int(ft["height"])
    scene.render.resolution_percentage = 100
    pa = float(ft.get("pixel_aspect") or 1.0)
    scene.render.pixel_aspect_x = pa if pa >= 1 else 1.0
    scene.render.pixel_aspect_y = 1.0 / pa if pa < 1 else 1.0
    scene.render.fps = int(ft["fps_num"])
    scene.render.fps_base = float(ft["fps_den"])
    scene.frame_start = int(fr["blender_start"])
    scene.frame_end = int(fr["blender_end"])
    scene.unit_settings.system = "METRIC"
    scene.unit_settings.scale_length = 1.0

    root = get_collection(COLLECTION_NAME, scene.collection)
    clear_collection(root)
    col_cam = get_collection(COLLECTION_NAME + " Camera", root)
    col_pts = get_collection(COLLECTION_NAME + " Track Points", root)
    col_scene = get_collection(COLLECTION_NAME + " Scene", root)
    col_obj = get_collection(COLLECTION_NAME + " Objects", root)

    # ---- camera ----
    cam_data = bpy.data.cameras.new("Solved Camera")
    cam_data.sensor_fit = "HORIZONTAL"
    cam_data.sensor_width = float(intr["sensor_width_mm"])
    cam_data.sensor_height = float(intr["sensor_width_mm"]) * ft["height"] / ft["width"]
    cam_data.lens = float(intr["focal_mm"])
    cam_data.shift_x = float(intr["shift_x"])
    cam_data.shift_y = float(intr["shift_y"])
    cam_data.clip_start = 0.01
    cam = bpy.data.objects.new("Solved Camera", cam_data)
    col_cam.objects.link(cam)
    cam.rotation_mode = "QUATERNION"
    scene.camera = cam

    prev_q = None
    for c in data["camera"]:
        f = c["blender_frame"]
        m = matrix3(c["rotation_matrix"])
        q = m.to_quaternion()
        if prev_q is not None and prev_q.dot(q) < 0:   # keep quaternion signs continuous
            q.negate()
        prev_q = q
        cam.location = Vector(c["location"])
        cam.rotation_quaternion = q
        cam.keyframe_insert("location", frame=f)
        cam.keyframe_insert("rotation_quaternion", frame=f)
        if intr.get("variable_focal"):
            cam_data.lens = float(c["focal_mm"])
            cam_data.keyframe_insert("lens", frame=f)
    set_linear(cam)
    set_linear(cam_data)
    cam["camtrack_solve_mode"] = data["solve"]["mode"]
    cam["camtrack_mean_reprojection_error_px"] = float(data["solve"]["stats"].get("mean_error_px_original_res", -1))
    cam["camtrack_k1"] = float(intr["k1"])
    cam["camtrack_k2"] = float(intr["k2"])

    # ---- footage as camera background + movie clip with lens distortion ----
    footage_path = os.path.join(base_dir, ft["relative_path"])
    if os.path.exists(footage_path):
        clip = bpy.data.movieclips.load(footage_path)
        clip.frame_start = int(fr["frame_offset"])   # clip frame 1 == footage frame 0
        tc = clip.tracking.camera
        try:
            tc.sensor_width = float(intr["sensor_width_mm"])
            tc.units = "PIXELS"
            tc.focal_length_pixels = float(intr["focal_px"])
            tc.distortion_model = "POLYNOMIAL"
            tc.k1, tc.k2, tc.k3 = float(intr["k1"]), float(intr["k2"]), 0.0
            if hasattr(tc, "principal_point_pixels"):
                # Blender uses a bottom-left origin with pixel-edge coordinates
                tc.principal_point_pixels = (intr["cx_px"] + 0.5, ft["height"] - (intr["cy_px"] + 0.5))
            else:
                tc.principal = (intr["cx_px"] + 0.5, ft["height"] - (intr["cy_px"] + 0.5))
        except Exception as e:  # pragma: no cover - API differences
            print("CamTrack: could not set clip camera intrinsics:", e)
        cam_data.show_background_images = True
        bg = cam_data.background_images.new()
        bg.source = "MOVIE_CLIP"
        bg.clip = clip
        bg.alpha = 1.0
        bg.frame_method = "FIT"
        try:
            # show the footage undistorted so it lines up with Blender's pinhole camera
            bg.clip_user.use_render_undistorted = abs(intr["k1"]) > 1e-6 or abs(intr["k2"]) > 1e-6
        except Exception:
            pass
        scene.active_clip = clip
    else:
        print("CamTrack: footage not found at", footage_path, "- camera background not set")

    # ---- scale-aware display sizes ----
    locs = [Vector(p["location"]) for p in data["points"]]
    if locs:
        cen = sum(locs, Vector()) / len(locs)
        ext = sorted((v - cen).length for v in locs)[int(len(locs) * 0.9)] if len(locs) > 1 else 1.0
    else:
        ext = 5.0
    psize = POINT_EMPTY_SIZE or max(ext * 0.01, 1e-3)

    # ---- track points ----
    pts = [p for p in data["points"] if p["reliable"] or not ONLY_RELIABLE_POINTS]
    if CREATE_POINT_EMPTIES:
        for p in pts:
            e = bpy.data.objects.new(f"Track {p['id']}", None)
            e.empty_display_type = "PLAIN_AXES" if p["reliable"] else "SPHERE"
            e.empty_display_size = psize
            e.location = p["location"]
            e["camtrack_error_px"] = p["error_px"]
            e["camtrack_reliable"] = p["reliable"]
            col_pts.objects.link(e)
    # point cloud mesh with colours
    me = bpy.data.meshes.new("Track Point Cloud")
    me.from_pydata([p["location"] for p in pts], [], [])
    try:
        attr = me.color_attributes.new("Col", "BYTE_COLOR", "POINT")
        for i, p in enumerate(pts):
            r, g, b = (c / 255.0 for c in p["color"])
            attr.data[i].color = (r, g, b, 1.0)
    except Exception:
        pass
    pc = bpy.data.objects.new("Track Point Cloud", me)
    col_scene.objects.link(pc)

    # ---- world origin ----
    org = bpy.data.objects.new("World Origin", None)
    org.empty_display_type = "ARROWS"
    org.empty_display_size = max(ext * 0.15, 0.01)
    col_scene.objects.link(org)

    # ---- ground plane ----
    gp = data["ground_plane"]
    s = gp["size"] / 2
    gme = bpy.data.meshes.new("Ground Plane")
    gme.from_pydata([(-s, -s, 0), (s, -s, 0), (s, s, 0), (-s, s, 0)], [], [(0, 1, 2, 3)])
    gob = bpy.data.objects.new("Ground Plane", gme)
    m = matrix3(gp["rotation_matrix"]).to_4x4()
    m.translation = Vector(gp["location"])
    gob.matrix_world = m
    mat = bpy.data.materials.new("CamTrack Ground")
    mat.diffuse_color = (0.8, 0.15, 0.1, 0.35)
    gme.materials.append(mat)
    try:
        gob.is_shadow_catcher = True
    except Exception:
        pass
    gob.display_type = "WIRE" if len(pts) > 0 else "SOLID"
    col_scene.objects.link(gob)

    # ---- user objects (nulls, solids, anchors, ground-plane objects) ----
    for ob in data["objects"]:
        m = matrix3(ob["rotation"]).to_4x4()
        m.translation = Vector(ob["location"])
        sz = float(ob["size"])
        if ob["type"] in ("null", "anchor"):
            e = bpy.data.objects.new(ob["name"], None)
            e.empty_display_type = "PLAIN_AXES" if ob["type"] == "null" else "ARROWS"
            e.empty_display_size = sz
        else:
            h = sz / 2 if ob["type"] == "solid" else sz * 2
            mme = bpy.data.meshes.new(ob["name"])
            mme.from_pydata([(-h, -h, 0), (h, -h, 0), (h, h, 0), (-h, h, 0)], [], [(0, 1, 2, 3)])
            e = bpy.data.objects.new(ob["name"], mme)
            if ob["type"] == "ground_plane":
                try:
                    e.is_shadow_catcher = True
                except Exception:
                    pass
        e.matrix_world = m
        e["camtrack_type"] = ob["type"]
        col_obj.objects.link(e)

    scene.frame_set(scene.frame_start)
    print(f"CamTrack: built camera ({len(data['camera'])} frames), {len(pts)} points, "
          f"{len(data['objects'])} objects; mean reprojection error "
          f"{data['solve']['stats'].get('mean_error_px_original_res', float('nan')):.3f}px")
    return data


if __name__ == "__main__":
    build()
    argv = sys.argv[sys.argv.index("--") + 1:] if "--" in sys.argv else []
    if "--save" in argv:
        out = argv[argv.index("--save") + 1]
        bpy.ops.wm.save_as_mainfile(filepath=os.path.abspath(out))
        print("CamTrack: saved", out)
